:root {
  --ink: #18323d;
  --paper: #fffdf7;
  --water: #d9f0ee;
  --teal: #197c79;
  --coral: #ef7659;
  --line: #b8d7d4;
}

.ferry-pass {
  width: 460px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.pass-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--water);
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.pass-title {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  color: var(--paper);
  background: var(--coral);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.crossing {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 16px;
}

.place {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
}

.arrow {
  color: var(--teal);
  font-size: 22px;
  font-weight: 700;
}

.pass-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.departure {
  margin: 0;
  font-size: 14px;
}

button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 7px;
  font-weight: 800;
}
